"""Prompts fixed before eval; no gold fields or controller hints in consumer input."""
import hashlib
import json
ANSWER = '''Answer the question using the supplied video frames and their actual timestamps. Treat the images as observations from one video. Give a direct answer of at most 30 words and cite only the IDs of input groups that support it. Never invent IDs. When there are no images, citations must be an empty list []. Use at most six distinct input IDs. If the observations do not determine the answer, say that the available evidence is insufficient. Do not describe your reasoning. Return only a JSON object with keys "answer" (string) and "citations" (list of input ID strings).\nQuestion: {question}'''
CONTROL_R1 = '''You are selecting more observations to answer a question about a video. The supplied images are the first three retrieved groups, with actual timestamps. Write one concise search query that refines the original question using these observations. Do not answer the question. Return only JSON with key "queries", containing exactly one short string.\nQuestion: {question}'''
CONTROL_R2 = '''You are selecting more observations to answer a question about a video. The supplied images are the first three retrieved groups, with actual timestamps. Identify up to two missing facts or temporal relations needed to answer. Write one concise search query per missing fact or relation. Do not answer the question. Return only JSON with key "queries", containing one or two short strings.\nQuestion: {question}'''
JUDGE = '''Evaluate each anonymous prediction against its question and reference answer. Use the same strict rule for every prediction: "correct" only if the conclusion is semantically correct, with no meaning-changing omission or contradiction; otherwise "incorrect". Use "uncertain" only when reference ambiguity prevents a reliable decision. A statement that evidence is insufficient does not answer a determinate reference question. Extra claims that contradict the reference make an answer incorrect. You cannot inspect the video. Return only a JSON object with a "results" array. For each supplied id, return keys "id", "verdict" ("correct", "incorrect", or "uncertain"), and "reason" (at most eight words).\nItems:\n{items}'''

def identity():
    prompts={k:globals()[k] for k in ('ANSWER','CONTROL_R1','CONTROL_R2','JUDGE')}
    return {'prompts':prompts,'sha256':hashlib.sha256(json.dumps(prompts,sort_keys=True).encode()).hexdigest()}
